const financeFiscalYears=[
  {id:'FY-2026',name:'FY 2025–26',start:'01 Oct 2025',end:'30 Sep 2026',active:true,periods:['Oct 2025','Nov 2025','Dec 2025','Jan 2026','Feb 2026','Mar 2026','Apr 2026','May 2026','Jun 2026','Jul 2026','Aug 2026','Sep 2026'].map((name,index)=>({id:`PER-2026-${String(index+1).padStart(2,'0')}`,name,sequence:index+1,start:`01 ${name}`,end:`${[31,30,31,31,28,31,30,31,30,31,31,30][index]} ${name}`,status:index>=10?'open':'closed',closedBy:index>=10?'—':'Farah Ahmed',closedAt:index>=10?'—':`04 ${['Nov 2025','Dec 2025','Jan 2026','Feb 2026','Mar 2026','Apr 2026','May 2026','Jun 2026','Jul 2026','Aug 2026'][index]}`}))},
  {id:'FY-2025',name:'FY 2024–25',start:'01 Oct 2024',end:'30 Sep 2025',active:false,periods:Array.from({length:12},(_,index)=>{const name=['Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep'][index]+' '+(index<3?'2024':'2025');return {id:`PER-2025-${String(index+1).padStart(2,'0')}`,name,sequence:index+1,start:`01 ${name}`,end:`${[31,30,31,31,28,31,30,31,30,31,31,30][index]} ${name}`,status:'closed',closedBy:'Farah Ahmed',closedAt:'06 Oct 2025'}})}
];
const financeYearFilter={search:'',status:'all'};
let financeCloseYear='FY-2026',financeClosePeriod='PER-2026-12';
const financePeriodModules=[
  {code:'COMMERCE',name:'Commerce',status:'closed',actor:'Farah Ahmed',at:'24 Sep 2026, 4:10 PM',reason:'September order settlements reviewed',readiness:'Passed'},
  {code:'INVENTORY',name:'Inventory',status:'closed',actor:'Farah Ahmed',at:'24 Sep 2026, 4:30 PM',reason:'Stock valuation confirmed',readiness:'Passed'},
  {code:'PROCUREMENT',name:'Procurement',status:'open',actor:'—',at:'—',reason:'No reason recorded',readiness:'Warnings'},
  {code:'PAYMENT',name:'Payment Management',status:'open',actor:'—',at:'—',reason:'No reason recorded',readiness:'Blocked'},
  {code:'TRAINING',name:'Training',status:'open',actor:'—',at:'—',reason:'No reason recorded',readiness:'Passed'},
  {code:'FINANCE',name:'Finance',status:'open',actor:'—',at:'—',reason:'No reason recorded',readiness:'Blocked'}
];
function financePostingRules(detail=false){return `<div class="fin-period-info"><strong>Posting rules</strong><p>Only open periods accept postings. Closed periods block journals, invoices, bills, and payments.${detail?' The calendar dates and period count are locked because posted accounting activity exists. Names remain editable.':''}</p>${detail?'':`<a href="#/app/finance/period-close">Review Period Close Center ↗</a>`}</div>`;}
function renderFinancePeriods(){const rows=financeFiscalYears.filter(year=>(!financeYearFilter.search||year.name.toLowerCase().includes(financeYearFilter.search.toLowerCase()))&&(financeYearFilter.status==='all'||(financeYearFilter.status==='active')===year.active));const body=rows.map(year=>`<tr><td><strong>${year.name}</strong><small>${year.active?'Current posting calendar':'Historical calendar'}</small></td><td><span class="fin-pill ${year.active?'good':'muted'}">${year.active?'Active':'Historical'}</span></td><td>${year.start} to ${year.end}</td><td><div class="fin-period-count"><strong>${year.periods.length} total</strong><span>${year.periods.filter(p=>p.status==='open').length} open</span><span>${year.periods.filter(p=>p.status==='closed').length} closed</span></div></td><td><a href="#/app/finance/periods/${year.id}">View details ↗</a></td></tr>`).join('');return `<div class="finance-mock">${financeHero('Fiscal years & accounting periods','Manage fiscal calendars and open a dedicated workspace for each year’s posting windows.',`<button class="btn primary" data-fin-calendar-new>New fiscal calendar</button><button class="btn" data-fin-refresh>Refresh</button>`)}${financePostingRules()}${financeCard('Fiscal calendars',`<div class="fin-filters fin-year-filters"><label>Search fiscal years<input data-fin-year-filter="search" value="${esc(financeYearFilter.search)}" placeholder="Search by name..."></label><label>Status<select data-fin-year-filter="status"><option value="all">All years</option><option value="active" ${financeYearFilter.status==='active'?'selected':''}>Active</option><option value="historical" ${financeYearFilter.status==='historical'?'selected':''}>Historical</option></select></label><span class="fin-count-chip">${rows.length} fiscal years</span></div>${financeTable(['Fiscal year','Status','Date range','Periods','Action'],body,'No fiscal years match the current filters.')}`,'','The current year’s posting windows and historical calendars.')}</div>`;}
function renderFinancePeriodDetail(id){const year=financeFiscalYears.find(y=>y.id===id);if(!year)return `<div class="finance-mock">${financeHero('Fiscal year unavailable','The requested fiscal year could not be loaded in the current organization context.',`<a class="btn" href="#/app/finance/periods">Back to fiscal years</a>`)}</div>`;const open=year.periods.filter(p=>p.status==='open').length,body=year.periods.map(period=>`<tr><td><strong>P${String(period.sequence).padStart(2,'0')} · ${period.name}</strong></td><td>${period.start||'01 '+period.name} to ${period.end||'30 '+period.name}</td><td><span class="fin-pill ${period.status==='open'?'good':'muted'}">${period.status}</span></td><td>${period.closedBy}</td><td>${period.closedAt}</td><td><button class="fin-table-action" data-fin-period-action="${period.id}">Actions ···</button></td></tr>`).join('');return `<div class="finance-mock">${financeHero(`${year.name} · Accounting periods`,`Manage posting windows from ${year.start} to ${year.end}.`,`<span class="fin-hero-pill">${year.active?'Active':'Historical'} fiscal year</span><label class="fin-hero-select">Fiscal year<select data-fin-year-nav><option value="FY-2026" ${year.id==='FY-2026'?'selected':''}>FY 2025–26</option><option value="FY-2025" ${year.id==='FY-2025'?'selected':''}>FY 2024–25</option></select></label><a class="btn" href="#/app/finance/periods">Back to fiscal years</a><a class="btn" href="#/app/finance/period-close">Period Close Center</a><button class="btn" data-fin-year-edit="${year.id}">Edit fiscal year</button><button class="btn primary" data-fin-period-adjust="${year.id}">Adjust periods</button>`)}${financePostingRules(true)}<div class="fin-summary fin-period-summary">${[['Total periods',year.periods.length],['Open periods',open],['Closed periods',year.periods.length-open],['Date range',`${year.start} – ${year.end}`]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>${financeCard('Accounting periods',financeTable(['Period','Posting window','Status','Closed by','Last closed','Action'],body,'No accounting periods exist for this fiscal year.'),`<button class="btn" data-fin-refresh>Refresh</button>`,'Close or reopen individual periods while preserving the activity history.')}</div>`;}
function financeCloseChecks(){return [
  {label:'Draft journals',message:'7 unposted journal entries remain in this fiscal period.',count:7,status:'blocked',route:'journals?status=draft',action:'Review journals'},
  {label:'Payment reconciliation',message:'1 payment exception still needs provider confirmation.',count:1,status:'warning',route:'../payment-management/reconciliation/review',action:'Review payments'},
  {label:'Supplier bills',message:'2 bills are awaiting final approval.',count:2,status:'warning',route:'payables',action:'Review bills'}
]}
function renderFinancePeriodClose(){const year=financeFiscalYears.find(y=>y.id===financeCloseYear)||financeFiscalYears[0],period=year.periods.find(p=>p.id===financeClosePeriod)||year.periods.at(-1),closed=financePeriodModules.filter(m=>m.status==='closed').length,checks=financeCloseChecks();return `<div class="finance-mock">${financeHero('Period close center','Review readiness, close posting windows by module, and keep a complete audit trail for each accounting period.',`<button class="btn" data-fin-refresh>Refresh</button>`)}<div class="fin-close-select"><label>Fiscal year<select data-fin-close-select="year">${financeFiscalYears.map(y=>`<option value="${y.id}" ${year.id===y.id?'selected':''}>${y.name}</option>`).join('')}</select></label><label>Period<select data-fin-close-select="period">${year.periods.map(p=>`<option value="${p.id}" ${period.id===p.id?'selected':''}>P${String(p.sequence).padStart(2,'0')} · ${p.name}</option>`).join('')}</select></label></div><section class="fin-close-summary"><div><span class="eyebrow">SELECTED PERIOD</span><h2>${period.name}</h2><p>${period.start||'01 '+period.name} to ${period.end||'30 '+period.name}</p><small>${closed} of ${financePeriodModules.length-1} modules closed · Updated 25 Sep 2026, 9:45 AM</small></div><div class="fin-readiness-status"><span>CLOSE READINESS</span><strong>Blocked</strong><small>1 blocker · 2 warnings</small></div><div class="fin-close-actions"><button class="btn" data-fin-close-action="closeAll">Close remaining modules</button><button class="btn" data-fin-close-action="reopenAll">Reopen all modules</button></div></section>${financeCard('Period-close readiness',`<div class="fin-readiness-grid">${checks.map(check=>`<article class="${check.status}"><div><strong>${check.label}</strong><span>${check.status}</span></div><p>${check.message}</p><footer><small>${check.count} items</small><a href="#/app/${check.route.startsWith('..')?check.route.slice(3):'finance/'+check.route}">${check.action} ↗</a></footer></article>`).join('')}</div>`,'<span class="fin-pill">Blocked</span>','Resolve blocking issues before posting is locked.')}${financeCard('Posting windows',`<div class="fin-module-grid">${financePeriodModules.map(module=>`<article class="${module.status}"><div class="fin-module-top"><div><span>${module.code}</span><h3>${module.name}</h3></div><b class="fin-pill ${module.status==='open'?'good':'muted'}">${module.status}</b></div><div class="fin-module-readiness"><span>Readiness</span><b>${module.readiness}</b></div><dl><div><dt>${module.status==='closed'?'Closed':'Reopened'} by</dt><dd>${module.actor}</dd></div><div><dt>${module.status==='closed'?'Closed':'Reopened'} at</dt><dd>${module.at}</dd></div><div><dt>Reason</dt><dd>${module.reason}</dd></div></dl><button class="btn" data-fin-module-action="${module.code}">${module.status==='closed'?'Reopen':'Close'} module</button></article>`).join('')}</div>`,`<button class="btn" data-fin-close-history>View close history</button>`,'Close modules independently as each team completes period-end work.')}</div>`;}
function financePeriodDrawer(kind,id){const year=financeFiscalYears.find(y=>y.id===id||y.periods.some(p=>p.id===id))||financeFiscalYears[0],period=year.periods.find(p=>p.id===id),module=financePeriodModules.find(m=>m.code===id);if(kind==='calendar')return `<div class="fin-period-drawer"><p>Create a fiscal year and auto-generate evenly divided accounting periods.</p><div class="fin-drawer-grid"><label>Fiscal year name *<input value="FY 2026–27"></label><label>Period count *<input type="number" min="1" max="24" value="12"></label><label>Start date *<input type="date" value="2026-10-01"></label><label>End date *<input type="date" value="2027-09-30"></label></div><div class="fin-period-info"><strong>Calendar guidance</strong><p>Use 12 periods for monthly calendars or choose another evenly divisible count for your fiscal structure.</p></div><button class="btn primary" data-fin-period-save>Create calendar</button></div>`;if(kind==='year')return `<div class="fin-period-drawer"><p>Update the fiscal year identity. Posted activity locks dates and period count.</p><label>Fiscal year name *<input value="${year.name}"></label><div class="fin-drawer-grid"><label>Start date *<input type="date" value="2025-10-01" disabled></label><label>End date *<input type="date" value="2026-09-30" disabled></label></div><button class="btn primary" data-fin-period-save>Save changes</button></div>`;if(kind==='adjust')return `<div class="fin-period-drawer"><p>Regenerate the complete period calendar using the same fiscal-year date range.</p><label>Number of periods *<input type="number" value="12" min="1" max="24" disabled></label><label>Reason<input placeholder="Why is the calendar being adjusted?" disabled></label><div class="fin-period-info"><strong>Calendar locked</strong><p>Posted accounting activity prevents replacing this period structure.</p></div></div>`;if(kind==='period')return `<div class="fin-period-drawer"><p>Rename the period or adjust its posting window when the calendar is still editable.</p><label>Period name *<input value="${period?.name||''}"></label><div class="fin-drawer-grid"><label>Start date *<input type="date" disabled></label><label>End date *<input type="date" disabled></label></div><div class="fin-period-info"><strong>Dates are locked</strong><p>Posted activity prevents changing period boundaries. The period name can still be updated.</p></div><button class="btn primary" data-fin-period-save>Save changes</button></div>`;if(kind==='history')return `<div class="fin-period-drawer"><p>Recent close and reopen actions for the selected accounting period.</p><div class="fin-history-row"><strong>Commerce closed</strong><span>Farah Ahmed · 24 Sep 2026, 4:10 PM</span><p>September order settlements reviewed</p></div><div class="fin-history-row"><strong>Inventory closed</strong><span>Farah Ahmed · 24 Sep 2026, 4:30 PM</span><p>Stock valuation confirmed</p></div></div>`;return `<div class="fin-period-drawer"><p>Review the posting impact and document this period-close action.</p><div class="fin-period-info"><strong>${module?module.name:'All remaining modules'} · ${financeFiscalYears[0].name}</strong><p>${module?.readiness==='Blocked'?'This module has blocking readiness checks. Resolve them before closing.':'Posting control changes are retained in the audit trail.'}</p></div><label>Audit reason<textarea rows="4" placeholder="Add a concise reason for this period-close action"></textarea></label><button class="btn primary" data-fin-period-save ${module?.readiness==='Blocked'?'disabled':''}>Preview action</button></div>`;}
root.addEventListener('input',event=>{if(event.target.dataset.finYearFilter==='search')financeYearFilter.search=event.target.value});
root.addEventListener('change',event=>{if(event.target.dataset.finYearFilter==='status'){financeYearFilter.status=event.target.value;render()}if(event.target.dataset.finYearFilter==='search')render();if(event.target.dataset.finYearNav)location.hash=`#/app/finance/periods/${event.target.value}`;if(event.target.dataset.finCloseSelect==='year'){financeCloseYear=event.target.value;financeClosePeriod=(financeFiscalYears.find(y=>y.id===financeCloseYear)?.periods.at(-1)?.id)||'';render()}if(event.target.dataset.finCloseSelect==='period'){financeClosePeriod=event.target.value;render()}});
root.addEventListener('click',event=>{let kind='',id='';if(event.target.closest('[data-fin-calendar-new]'))kind='calendar';else if(event.target.closest('[data-fin-year-edit]')){kind='year';id=event.target.closest('[data-fin-year-edit]').dataset.finYearEdit}else if(event.target.closest('[data-fin-period-adjust]')){kind='adjust';id=event.target.closest('[data-fin-period-adjust]').dataset.finPeriodAdjust}else if(event.target.closest('[data-fin-period-action]')){kind='period';id=event.target.closest('[data-fin-period-action]').dataset.finPeriodAction}else if(event.target.closest('[data-fin-close-history]'))kind='history';else if(event.target.closest('[data-fin-close-action]')){kind='action';id=event.target.closest('[data-fin-close-action]').dataset.finCloseAction}else if(event.target.closest('[data-fin-module-action]')){kind='module';id=event.target.closest('[data-fin-module-action]').dataset.finModuleAction}if(kind){activeAction={calendar:'Create fiscal calendar',year:'Edit fiscal year',adjust:'Adjust accounting periods',period:'Edit accounting period',history:'Close history',action:'Period control',module:'Module control'}[kind];activeOverlayHTML=financePeriodDrawer(kind,id);activeOverlayClass='fin-period-overlay';drawer='original';render();return}if(event.target.closest('[data-fin-period-save]')){drawer='';flash('Sample period action recorded in this design preview.');return}});
